import{_ as n,a0 as s,w as i,s as c,ao as l,I as p,x as a,a1 as r,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"使用 Linux 的 strace 命令跟蹤/調試程序的常用選項 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Linux 的 strace 命令跟蹤/調試程序的常用選項 | LCTT (201409) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Linux 的 strace 命令跟蹤/調試程序的常用選項 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Linux 的 strace 命令跟蹤/調試程序的常用選項 | LCTT (201409) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201409/20140819 8 Options to Trace or Debug Programs using Linux strace Command","title":"使用 Linux 的 strace 命令跟蹤/調試程序的常用選項","tag":"201409","desc":""},"relativePath":"201409/20140819 8 Options to Trace or Debug Programs using Linux strace Command.md","filePath":"[post].md"}'),d={name:"201409/20140819 8 Options to Trace or Debug Programs using Linux strace Command.md"};function m(u,e,h,g,x,f){const t=s("Link");return i(),c("div",null,[e[13]||(e[13]=l(`<h1 id="使用-linux-的-strace-命令跟蹤-調試程序的常用選項" tabindex="-1">使用 Linux 的 strace 命令跟蹤/調試程序的常用選項 <a class="header-anchor" href="#使用-linux-的-strace-命令跟蹤-調試程序的常用選項" aria-label="Permalink to “使用 Linux 的 strace 命令跟蹤/調試程序的常用選項”">​</a></h1><p>在調試的時候，strace能幫助你追蹤到一個程序所執行的系統調用。當你想知道程序和操作系統如何交互的時候，這是極其方便的，比如你想知道執行了哪些系統調用，並且以何種順序執行。</p><p>這個簡單而又強大的工具幾乎在所有的Linux操作系統上可用，並且可被用來調試大量的程序。</p><h3 id="命令用法" tabindex="-1">命令用法 <a class="header-anchor" href="#命令用法" aria-label="Permalink to “命令用法”">​</a></h3><p>讓我們看看strace命令如何追蹤一個程序的執行情況。</p><p>最簡單的形式，strace後面可以跟任何命令。它將列出許許多多的系統調用。一開始，我們並不能理解所有的輸出，但是如果你正在尋找一些特殊的東西，那麼你應該能從輸出中發現它。</p><p>讓我們來看看簡單命令ls的系統調用跟蹤情況。</p><pre><code>raghu@raghu-Linoxide ~ $ strace ls
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/01.strace_ls.png" alt="Stracing ls command"></p><p>這是strace命令輸出的前幾行。其他輸出被截去了。</p><p><img src="http://linoxide.com/wp-content/uploads/2014/08/02.strace_ls_write.png" alt="Strace write system call (ls)"></p><p>上面的輸出部分展示了write系統調用，它把當前目錄的列表輸出到標準輸出。</p><p>下面的圖片展示了使用ls命令列出的目錄內容（沒有使用strace）。</p><pre><code>raghu@raghu-Linoxide ~ $ ls
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/03.ls_.png" alt="ls command output"></p><h4 id="選項1-尋找被程序讀取的配置文件" tabindex="-1">選項1 尋找被程序讀取的配置文件 <a class="header-anchor" href="#選項1-尋找被程序讀取的配置文件" aria-label="Permalink to “選項1 尋找被程序讀取的配置文件”">​</a></h4><p>Strace 的用法之一（除了調試某些問題以外）是你能找到被一個程序讀取的配置文件。例如，</p><pre><code>raghu@raghu-Linoxide ~ $ strace php 2&gt;&amp;1 | grep php.ini
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/04.strace_php_configuration.png" alt="Strace config file read by program"></p><h4 id="選項2-跟蹤指定的系統調用" tabindex="-1">選項2 跟蹤指定的系統調用 <a class="header-anchor" href="#選項2-跟蹤指定的系統調用" aria-label="Permalink to “選項2 跟蹤指定的系統調用”">​</a></h4><p>strace命令的-e選項僅僅被用來展示特定的系統調用（例如，open，write等等）</p><p>讓我們跟蹤一下cat命令的‘open’系統調用。</p><pre><code>raghu@raghu-Linoxide ~ $ strace -e open cat dead.letter
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/05.strace_open_systemcall.png" alt="Stracing specific system call (open here)"></p><h4 id="選項3-跟蹤進程" tabindex="-1">選項3 跟蹤進程 <a class="header-anchor" href="#選項3-跟蹤進程" aria-label="Permalink to “選項3 跟蹤進程”">​</a></h4><p>strace不但能用在命令上，而且通過使用-p選項能用在運行的進程上。</p><pre><code>raghu@raghu-Linoxide ~ $ sudo strace -p 1846
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/06.strace_process.png" alt="Strace a process"></p><h4 id="選項4-strace的統計概要" tabindex="-1">選項4 strace的統計概要 <a class="header-anchor" href="#選項4-strace的統計概要" aria-label="Permalink to “選項4 strace的統計概要”">​</a></h4><p>它包括系統調用的概要，執行時間，錯誤等等。使用-c選項能夠以一種整潔的方式展示：</p><pre><code>raghu@raghu-Linoxide ~ $ strace -c ls
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/07.strace_summary.png" alt="Strace summary display"></p><h4 id="選項5-保存輸出結果" tabindex="-1">選項5 保存輸出結果 <a class="header-anchor" href="#選項5-保存輸出結果" aria-label="Permalink to “選項5 保存輸出結果”">​</a></h4><p>通過使用-o選項可以把strace命令的輸出結果保存到一個文件中。</p><pre><code>raghu@raghu-Linoxide ~ $ sudo strace -o process_strace -p 3229
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/08.strace_output_file.png" alt="Strace a process"></p><p>之所以以sudo來運行上面的命令，是為了防止用户ID與所查看進程的所有者ID不匹配的情況。</p><h3 id="選項6-顯示時間戳" tabindex="-1">選項6 顯示時間戳 <a class="header-anchor" href="#選項6-顯示時間戳" aria-label="Permalink to “選項6 顯示時間戳”">​</a></h3><p>使用-t選項，可以在每行的輸出之前添加時間戳。</p><pre><code>raghu@raghu-Linoxide ~ $ strace -t ls
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/09.strace_timestamp.png" alt="Timestamp before each output line"></p><h4 id="選項7-更精細的時間戳" tabindex="-1">選項7 更精細的時間戳 <a class="header-anchor" href="#選項7-更精細的時間戳" aria-label="Permalink to “選項7 更精細的時間戳”">​</a></h4><p>-tt選項可以展示微秒級別的時間戳。</p><pre><code>raghu@raghu-Linoxide ~ $ strace -tt ls
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/010.strace_finer_timestamp.png" alt="Time - Microseconds"></p><p>-ttt也可以向上面那樣展示微秒級的時間戳，但是它並不是打印當前時間，而是顯示自從epoch（譯註：1970年1月1日00:00:00 UTC）以來的所經過的秒數。</p><pre><code>raghu@raghu-Linoxide ~ $ strace -ttt ls
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/011.strace_epoch_seconds.png" alt="Seconds since epoch"></p><h4 id="選項8-相對時間" tabindex="-1">選項8 相對時間 <a class="header-anchor" href="#選項8-相對時間" aria-label="Permalink to “選項8 相對時間”">​</a></h4><p>-r選項展示系統調用之間的相對時間戳。</p><pre><code>raghu@raghu-Linoxide ~ $ strace -r ls
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/012.strace_relative-time.png" alt="Relative Timestamp"></p><hr>`,53)),p("p",null,[e[1]||(e[1]=a("via: ",-1)),r(t,{href:"http://linoxide.com/linux-command/linux-strace-command-examples/"},{default:o(()=>[...e[0]||(e[0]=[a("http://linoxide.com/linux-command/linux-strace-command-examples/",-1)])]),_:1})]),p("p",null,[e[5]||(e[5]=a("作者：",-1)),r(t,{href:"http://linoxide.com/author/raghu/"},{default:o(()=>[...e[2]||(e[2]=[a("Raghu",-1)])]),_:1}),e[6]||(e[6]=a(" 譯者：",-1)),r(t,{href:"https://github.com/guodongxiaren"},{default:o(()=>[...e[3]||(e[3]=[a("guodongxiaren",-1)])]),_:1}),e[7]||(e[7]=a(" 校對：",-1)),r(t,{href:"https://github.com/wxy"},{default:o(()=>[...e[4]||(e[4]=[a("wxy",-1)])]),_:1})]),p("p",null,[e[10]||(e[10]=a("本文由 ",-1)),r(t,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[8]||(e[8]=[a("LCTT",-1)])]),_:1}),e[11]||(e[11]=a(" 原創翻譯，",-1)),r(t,{href:"http://linux.cn/"},{default:o(()=>[...e[9]||(e[9]=[a("Linux中國",-1)])]),_:1}),e[12]||(e[12]=a(" 榮譽推出",-1))])])}const b=n(d,[["render",m]]);export{T as __pageData,b as default};
